<div class="heading"><div><span class="eyebrow">Каталог</span><h1>Мероприятия</h1></div><a class="button" href="/events/create">+ Новое мероприятие</a></div>
<form class="filters" method="get" action="/events"><label for="status">Статус</label><select id="status" name="status"><option value="">Все статусы</option><?php foreach (['draft'=>'Черновик','published'=>'Опубликовано','completed'=>'Завершено'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $status === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><button type="submit">Применить</button></form>
<div class="panel"><table><thead><tr><th>Мероприятие</th><th>Дата</th><th>Площадка</th><th>Статус</th><th></th></tr></thead><tbody>
<?php foreach ($events as $event): ?><tr><td><a class="item-title" href="/events/<?= e($event['id']) ?>"><?= e($event['title']) ?></a></td><td><?= e($event['date']) ?></td><td><?= e($venues[$event['venue_id']] ?? 'Не указана') ?></td><td><span class="pill <?= e($event['status']) ?>"><?= e(['draft'=>'Черновик','published'=>'Опубликовано','completed'=>'Завершено'][$event['status']] ?? $event['status']) ?></span></td><td><a href="/events/<?= e($event['id']) ?>">Подробнее</a></td></tr><?php endforeach; ?>
</tbody></table><?php if (!$events): ?><p class="empty">Мероприятия не найдены. Измените фильтр.</p><?php endif; ?></div>